"""Simulator for CS 456 Assignment 1. Do not edit this file.

Usage: python3 sim.py SCENARIO [FOLDER] [--test TEST]

Runs one call over the network described in the SCENARIO file, using the code
in FOLDER (default: this folder): joining with join.py (Part A), the setup
protocol in setup.py (Part B), then the call itself in call.py (Part C). A part
whose file is missing from FOLDER, as in baseline/, is skipped. A TEST file can
change how the join server and the setup messages behave.

Prints how the call went, writes logs/<scenario>-<folder>.json (for
replay.py) and logs/<scenario>-<folder>-packets.csv, and adds a line to
history.csv. Time is simulated and measured in milliseconds.
"""
import collections
import datetime
import hashlib
import heapq
import importlib.util
import json
import math
import os
import random
import subprocess
import sys
import traceback

import clock

HERE = os.path.dirname(os.path.abspath(__file__))
FPS = 25
FRAME_MS = 1000 / FPS
MTU = 1500
DEADLINE_MS = 200
JOIN_DELAY_MS = 20      # one-way delay of the byte stream to the join server
SETUP_TIMEOUT_MS = 5000  # a call whose camera hasn't started by then has failed
SETUP_BYTES = (b"\x01", b"\x02", b"\x03")  # first bytes of JOIN, ACCEPT and CONFIRM
FREEZE_GAP_MS = max(3 * FRAME_MS, FRAME_MS + 150)  # WebRTC's definition of a freeze
GLITCH_WEIGHT = 5.0  # each glitch costs as much as 5 perfect frames
FREEZE_WEIGHT = 1.0  # how much freeze time costs in the score
MAX_EVENTS_PER_MS = 1000000  # more than this in one ms of simulated time means time has stopped moving


class StudentError(Exception):
    """A mistake in the student's code that is best explained without a traceback."""


def check_bytes(value, what):
    if not isinstance(value, (bytes, bytearray)):
        raise TypeError("%s needs bytes, not %s" % (what, type(value).__name__))


class Sim:
    """Runs callbacks in order of simulated time."""

    def __init__(self):
        self.now = 0.0
        self.events = []
        self.count = 0  # breaks ties, so events at the same time run in the order they were added

    def at(self, t, fn, *args, last=False):
        """Run fn(*args) at time t; with last=True, after everything else that happens at time t."""
        self.count += 1
        heapq.heappush(self.events, (t, last, self.count, fn, args))

    def run(self, end):
        ms, count = None, 0
        while self.events and self.events[0][0] <= end:
            self.now, _, _, fn, args = heapq.heappop(self.events)
            count = count + 1 if int(self.now) == ms else 1
            ms = int(self.now)
            if count > MAX_EVENTS_PER_MS:
                raise StudentError("simulated time has stopped moving at %.1f ms: your code keeps setting timers "
                                   "(or sending packets) without letting time pass, for example a timer with a "
                                   "0 ms delay that sets itself again" % self.now)
            fn(*args)


class Link:
    """One direction of the link. The two directions have the same settings but work independently.

    Packets go onto the link one at a time at its rate. The rate and the delay
    can change over time. A packet that would have to wait longer than max_wait_ms
    behind earlier packets is dropped. Then it may be lost, and it arrives
    after delay_ms plus a random 0 to jitter_ms, so packets can be reordered.
    Losses come in bursts of loss_burst packets on average, with loss_rate of
    all packets lost in the long run.
    """

    def __init__(self, sim, cfg, rate, delay, rng, receive, direction, packet_log):
        self.sim, self.cfg, self.rate, self.delay, self.rng, self.receive = sim, cfg, rate, delay, rng, receive
        self.direction, self.packet_log = direction, packet_log  # every packet: [sent, direction, bytes, first byte, what happened, arrives]
        self.to_lose = {}  # first byte of a setup message -> how many more of them to lose (the test file's "setup" section)
        self.busy_until = 0.0  # when the last packet finishes going onto the link
        self.bad = False       # in a loss burst
        self.p_end_burst = 1 / cfg["loss_burst"]
        self.p_start_burst = cfg["loss_rate"] * self.p_end_burst / (1 - cfg["loss_rate"])

    def send(self, pkt):
        pkt = bytes(pkt)
        if len(pkt) > MTU:
            raise ValueError("packet of %d bytes is larger than the MTU (%d)" % (len(pkt), MTU))
        entry = [self.sim.now, self.direction, len(pkt), pkt[0] if pkt else None, None, None]
        self.packet_log.append(entry)
        if self.busy_until - self.sim.now > self.cfg["max_wait_ms"]:
            entry[4] = "dropped waiting"  # too much is already waiting
            return
        start = max(self.sim.now, self.busy_until)
        self.busy_until = start + len(pkt) * 8 / at(self.rate, start)  # kbps is bits per ms

        if self.to_lose.get(pkt[:1]):  # a setup message the test file asked to lose
            self.to_lose[pkt[:1]] -= 1
            entry[4] = "lost"
            return
        self.bad = self.rng.random() < (1 - self.p_end_burst if self.bad else self.p_start_burst)
        if self.bad:
            entry[4] = "lost"
            return
        arrive = self.busy_until + at(self.delay, self.busy_until) + self.rng.uniform(0, self.cfg["jitter_ms"])
        entry[4], entry[5] = "arrived", arrive
        self.sim.at(arrive, self.receive, pkt)


class Net:
    """Your code's connection to the network."""

    def __init__(self, link):
        self._link = link

    def send(self, pkt):
        """Send pkt (bytes, at most MTU long) to the other side."""
        check_bytes(pkt, "net.send")
        self._link.send(pkt)


class Frame:
    def __init__(self, id, time, data):
        self.id = id              # 0, 1, 2, ...
        self.time = time          # when the frame was captured
        self.data = data          # data[level] is the frame's bytes at that quality level


class Player:
    """Keeps delivered frames in a buffer and shows the next one every 1/FPS seconds."""

    def __init__(self, sim):
        self.sim = sim
        self.frames = []       # the player's own copy of the frames, filled in when the camera starts
        self.buffer = collections.deque()
        self.screen = []       # [time, frame id, level, kind] for every frame put on screen
        self.shown = set()
        self.newest = -1
        self.glitch_kinds = {"backwards": 0, "repeated": 0, "wrong bytes": 0}

    def show(self, frame_id, data):
        if not isinstance(frame_id, int) or isinstance(frame_id, bool):
            raise TypeError("player.show needs the frame id as an int, not %s" % type(frame_id).__name__)
        check_bytes(data, "player.show")
        self.buffer.append((frame_id, bytes(data)))

    def _tick(self):
        if not self.buffer:
            return
        frame_id, data = self.buffer.popleft()
        known = 0 <= frame_id < len(self.frames)
        if not known or data not in self.frames[frame_id].data:
            self.screen.append([self.sim.now, None, None, "glitch"])  # garbled picture
            self.glitch_kinds["wrong bytes"] += 1
            return
        level = self.frames[frame_id].data.index(data)
        if frame_id in self.shown or frame_id < self.newest:
            kind = "glitch"  # shown again, or the video jumps backwards
            self.glitch_kinds["repeated" if frame_id in self.shown else "backwards"] += 1
        elif self.sim.now <= self.frames[frame_id].time + DEADLINE_MS:
            kind = "in_time"
        else:
            kind = "late"
        if kind != "glitch":
            self.shown.add(frame_id)
            self.newest = frame_id
        self.screen.append([self.sim.now, frame_id, level, kind])


def schedule(value):
    """A setting that is either one number, or a list of [time_ms, value] changes."""
    return value if isinstance(value, list) else [[0, value]]


def at(schedule, t):
    """The value of a schedule at time t."""
    return [value for start, value in schedule if start <= t][-1]


def load(dir, name):
    spec = importlib.util.spec_from_file_location(name, os.path.join(dir, name + ".py"))
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def load_clip(clip):
    """data[i][level] is frame i's bytes at that level."""
    clip_dir = os.path.join(HERE, "clips", clip)
    levels = sorted(int(d) for d in os.listdir(clip_dir) if d.isdigit())
    count = len(os.listdir(os.path.join(clip_dir, "0")))
    data = []
    for i in range(count):
        data.append([])
        for level in levels:
            with open(os.path.join(clip_dir, str(level), "%04d.jpg" % (i + 1)), "rb") as f:
                data[i].append(f.read())
    return data


def has(impl, name):
    """Whether the folder being run has this file. A folder without it, like baseline/, skips that part."""
    return os.path.isfile(os.path.join(impl, name + ".py"))


def passcode_for(call):
    """The passcode for a call: 20 to 40 letters and digits. The same call always has the same passcode."""
    digest = hashlib.sha256(call.encode()).hexdigest()
    return digest[:20 + int(digest[-2:], 16) % 21]


def message(kind, payload):
    """A join protocol message: <kind> <length of payload> <payload>."""
    return b"%s %d %s" % (kind, len(payload), payload)


class JoinStream:
    """A reliable byte stream between the receiver and the join server (Part A).

    The join server waits for a complete request, JOIN <length> <call>, sends
    its whole reply at once (OK <length> <passcode> or ERR <length>
    no-such-call), and closes the stream. Every byte arrives, in order, but in
    pieces. recv(n) returns the next piece, or b"" once the stream is closed;
    arrived_at is when the last piece recv returned arrived.
    """

    def __init__(self, call, rng, knobs):
        self.call, self.rng, self.knobs = call, rng, knobs  # knobs: the test file's "join" section
        self.request = b""
        self.pieces = None  # [arrival time, bytes] for each piece of the reply
        self.arrived_at = 0.0
        self.reads_after_close = 0
        self.reply_kind = None  # "OK" or "ERR", once the join server has replied
        self.cut = False        # the stream closed before the whole reply was sent

    def send(self, data):
        check_bytes(data, "stream.send")
        self.request += bytes(data)
        if self.pieces is not None:
            return
        parts = self.request.split(b" ", 2)
        if len(parts) < 3 or not parts[1].isdigit() or len(parts[2]) < int(parts[1]):
            return  # the request is not complete yet
        call = parts[2][:int(parts[1])].decode(errors="replace")
        if parts[0] == b"JOIN" and call == self.call and self.knobs.get("reply", "ok") == "ok":
            reply = message(b"OK", passcode_for(call).encode())
        else:
            reply = message(b"ERR", b"no-such-call")
        self.reply_kind = reply.split(b" ")[0].decode()
        if "close_after" in self.knobs and self.knobs["close_after"] < len(reply):  # the stream closes partway through the reply
            reply = reply[:self.knobs["close_after"]]
            self.cut = True
        self.pieces, t = [], 2 * JOIN_DELAY_MS
        while reply:
            n = self.knobs.get("recv_bytes") or self.rng.randint(1, 5)
            self.pieces.append([t, reply[:n]])
            reply = reply[n:]
            t += self.rng.uniform(1, 10)

    def recv(self, n):
        if not isinstance(n, int) or n < 1:
            raise ValueError("stream.recv(n) needs n to be a whole number of at least 1, not %r" % (n,))
        if self.pieces is None:
            raise RuntimeError("recv would wait forever: the join server has not received a complete request")
        if not self.pieces:  # the join server has closed the stream
            self.reads_after_close += 1
            if self.reads_after_close > 1000:
                raise StudentError("the join server closed the stream, but your code keeps calling stream.recv. "
                                   "Once the stream is closed, recv returns b\"\" every time.")
            return b""
        t, piece = self.pieces[0]
        self.arrived_at = t
        if len(piece) > n:
            self.pieces[0][1] = piece[n:]
        else:
            self.pieces.pop(0)
        return piece[:n]


def score(frames, player):
    start = frames[0].time + DEADLINE_MS   # the first frame is due on screen
    end = frames[-1].time + DEADLINE_MS    # the last frame is due on screen
    # Only real frames, shown in time or late, end a freeze; a glitch does not change the picture properly.
    points = [start] + [t for t, _, _, kind in player.screen if start < t <= end and kind != "glitch"] + [end]
    gaps = [b - a for a, b in zip(points, points[1:]) if b - a >= FREEZE_GAP_MS]
    levels = len(frames[0].data)
    quality = sum((l + 1) / levels for _, _, l, kind in player.screen if kind == "in_time") / len(frames)
    glitches = sum(1 for s in player.screen if s[3] == "glitch")
    return {
        "score": quality - GLITCH_WEIGHT * glitches / len(frames) - FREEZE_WEIGHT * sum(gaps) / (end - start),
        "quality": quality,
        "glitches": glitches,
        "freezes": len(gaps),
        "freeze_ms": sum(gaps),
        "start_ms": start,
        "end_ms": end,
    }


def report(e):
    """Explain an error, pointing at the student's code rather than the simulator's."""
    if isinstance(e, StudentError):
        print("Error: %s" % e, file=sys.stderr)
        return
    ours = {os.path.join(HERE, "sim.py"), os.path.join(HERE, "clock.py")}
    tb = traceback.extract_tb(e.__traceback__)
    theirs = [f for f in tb if os.path.abspath(f.filename) not in ours and not f.filename.startswith("<")]
    # The simulator called one of the student's functions with arguments it does not take.
    wrong_call = (isinstance(e, TypeError) and tb and os.path.abspath(tb[-1].filename) in ours
                  and ("positional argument" in str(e) or "keyword argument" in str(e)))
    if not theirs and not wrong_call and not isinstance(e, SyntaxError):
        print("The simulator hit an unexpected error. Please report it, with your code and the scenario.", file=sys.stderr)
        traceback.print_exception(type(e), e, e.__traceback__)
        return
    when = " at %.1f ms of simulated time" % clock._sim.now if clock._sim else ""
    print("Error in your code%s:" % when, file=sys.stderr)
    print("".join(traceback.format_list(theirs) + traceback.format_exception_only(type(e), e)), end="", file=sys.stderr)
    if wrong_call:
        print("The simulator called one of your functions or methods with arguments it does not accept. "
              "Check that it is defined as the handout shows.", file=sys.stderr)


RUN = {}  # what this run is, for the history: scenario, folder and test file


def record_history(outcome):
    """Add one line to history.csv, next to this file: when this run happened, what it ran, and how it ended."""
    if not RUN:
        return  # the run did not get far enough to know what it was running
    fingerprint = hashlib.sha256()
    for name in ("join", "setup", "call"):
        path = os.path.join(RUN["impl"], name + ".py")
        if os.path.isfile(path):
            with open(path, "rb") as f:
                fingerprint.update(f.read())
    path = os.path.join(HERE, "history.csv")  # not in logs/, so cleaning up the logs does not delete it
    new = not os.path.exists(path)
    with open(path, "a") as f:
        if new:
            f.write("time,scenario,folder,test_file,score,code_fingerprint\n")
        f.write("%s,%s,%s,%s,%s,%s\n" % (datetime.datetime.now().isoformat(timespec="seconds"), RUN["scenario"],
                                          os.path.basename(RUN["impl"]), RUN["test"], outcome,
                                          fingerprint.hexdigest()[:12]))


def main():
    if os.environ.get("PYTHONHASHSEED") != "0":
        # Otherwise Python orders sets and dicts of strings and bytes differently in every run,
        # and code that loops over one could score differently each time. Run again with a fixed order.
        sys.exit(subprocess.call([sys.executable] + sys.argv, env=dict(os.environ, PYTHONHASHSEED="0")))
    try:
        run_call()
    except Exception as e:
        report(e)
        record_history("error")
        sys.exit(1)


USAGE = """usage: python3 sim.py SCENARIO [FOLDER] [--test TEST]
  SCENARIO  a scenario file, for example scenarios/random_loss.json
  FOLDER    the folder with the call.py to run, for example baseline (default: this folder)
  TEST      a test file that changes how the join server and the setup messages behave (see the handout)"""


KNOBS = {"join": {"reply", "recv_bytes", "close_after"}, "setup": {"lose", "wrong_passcode"}}
SETUP_NAMES = {"JOIN": b"\x01", "ACCEPT": b"\x02", "CONFIRM": b"\x03"}


def join_summary(passcode, stream, call, knobs):
    """One line on how Part A went, and whether that is what should have happened."""
    at = "at %.0f ms" % stream.arrived_at
    if stream.reply_kind == "ERR":
        why = "the join server replied ERR" + (", as the test file asked" if knobs.get("reply") == "err"
                                               else ", so check the request your code sent")
    elif stream.cut:
        why = "the stream closed before the whole reply arrived, as the test file asked"
    else:
        why = None
    if passcode is None and stream.reply_kind == "ERR" and knobs.get("reply") != "err":
        return "get_passcode returned None %s: the join server replied ERR, so check the request your code sent" % at
    if passcode is None:
        return "get_passcode returned None %s (%s)" % (at, "as it should: " + why if why else "but the join server sent a passcode")
    if why:
        return "get_passcode returned a passcode %s, but it should have returned None: %s" % (at, why)
    if passcode != passcode_for(call):
        return "get_passcode returned %r %s, but that is not the passcode the join server sent" % (passcode, at)
    return "the receiver had the passcode %s" % at


def check_knobs(test):
    """A test file: optional "join" and "setup" sections, for testing Parts A and B."""
    unknown = set(test) - set(KNOBS)
    if unknown:
        raise StudentError("the test file has %s; it can only have join and setup" % ", ".join(sorted(unknown)))
    for section, allowed in KNOBS.items():
        unknown = set(test.get(section, {})) - allowed
        if unknown:
            raise StudentError("the test file's %s section has %s; it can only have %s"
                               % (section, ", ".join(sorted(unknown)), ", ".join(sorted(allowed))))
    join, setup = test.get("join", {}), test.get("setup", {})
    if join.get("reply", "ok") not in ("ok", "err"):
        raise StudentError('in the test file, join reply must be "ok" or "err"')
    for key in ("recv_bytes", "close_after"):
        if key in join and (not isinstance(join[key], int) or join[key] < (1 if key == "recv_bytes" else 0)):
            raise StudentError("in the test file, join %s must be a whole number%s" % (key, " of at least 1" if key == "recv_bytes" else ""))
    for name, count in setup.get("lose", {}).items():
        if name not in SETUP_NAMES or not isinstance(count, int) or count < 0:
            raise StudentError('in the test file, setup lose must look like {"JOIN": 2, "CONFIRM": 1}')


def run_call():
    args, test_path = sys.argv[1:], None
    if "--test" in args:
        i = args.index("--test")
        if i + 1 >= len(args) or not os.path.isfile(args[i + 1]):
            raise StudentError("--test needs a test file that exists\n" + USAGE)
        test_path = args[i + 1]
        del args[i:i + 2]
    if len(args) not in (1, 2) or not os.path.isfile(args[0]):
        if len(args) in (1, 2) and not args[0].startswith("-"):
            print("There is no scenario file called %s" % args[0], file=sys.stderr)
        raise StudentError(USAGE)
    if len(args) == 2 and not os.path.isfile(os.path.join(args[1], "call.py")):
        raise StudentError("There is no call.py in the folder %s\n%s" % (args[1], USAGE))
    scenario_path = args[0]
    impl = os.path.abspath(args[1] if len(args) > 1 else HERE)
    test = {}
    if test_path:
        with open(test_path) as f:
            test = json.load(f)
    name = os.path.splitext(os.path.basename(scenario_path))[0]
    RUN.update(scenario=name, impl=impl, test=os.path.basename(test_path) if test_path else "")
    with open(scenario_path) as f:
        sc = json.load(f)
    check_knobs(test)
    rate = schedule(sc["rate_kbps"])
    delay = schedule(sc["link"]["delay_ms"])
    start_rate, rtt = at(rate, 0), 2 * at(delay, 0)
    data = load_clip(sc["clip"])

    sim = Sim()
    clock._sim = sim
    player = Player(sim)
    random.seed(sc["seed"])  # so the student's own use of random gives the same result every run
    # Each side gets its own copy of the student's modules, so the two sides share no variables.
    sender_call, receiver_call = load(impl, "call"), load(impl, "call")
    sender_setup = load(impl, "setup") if has(impl, "setup") else None
    receiver_setup = load(impl, "setup") if has(impl, "setup") else None
    setups, endpoints = {}, {}  # "sender" and "receiver" -> the student's objects on that side
    frames = []

    delivered = collections.Counter()  # (side, first byte) -> setup messages handed to that side's setup code
    late = collections.Counter()       # side -> setup-looking packets that arrived after that side's call had started

    def arrive(side, pkt):  # setup messages go to the setup code, everything else to the Sender or Receiver
        if pkt[:1] in SETUP_BYTES:
            target = setups.get(side)
            if target is not None:
                delivered[side, pkt[:1]] += 1
            if side in endpoints:
                late[side] += 1
        else:
            target = endpoints.get(side)
            if side == "receiver":  # the first video packet shows the CONFIRM got through
                setups.pop("receiver", None)
        if target is not None:
            target.on_packet(pkt)

    packet_log = []
    link_cfg = dict(sc["link"])
    if "lose" in test.get("setup", {}):  # a controlled experiment: only the setup messages the test file names are lost
        link_cfg["loss_rate"] = 0.0
    to_receiver = Link(sim, link_cfg, rate, delay, random.Random("%s-to-receiver" % sc["seed"]),
                       lambda p: arrive("receiver", p), "to receiver", packet_log)
    to_sender = Link(sim, link_cfg, rate, delay, random.Random("%s-to-sender" % sc["seed"]),
                     lambda p: arrive("sender", p), "to sender", packet_log)
    sender_net, receiver_net = Net(to_receiver), Net(to_sender)

    def receiver_ready(*args):
        if len(args) != 2:
            raise TypeError("on the receiver's side, call start_call(rate_kbps, rtt_ms), with two arguments")
        if "receiver" not in endpoints:
            endpoints["receiver"] = receiver_call.Receiver(receiver_net, args[0], args[1], player)

    def sender_ready(*args):  # the call starts: create the Sender and start the camera
        if args:
            raise TypeError("on the sender's side, call start_call() with no arguments")
        if "sender" in endpoints:
            return
        setups.pop("sender", None)  # setup messages to the sender are dropped from now on
        endpoints["sender"] = sender_call.Sender(sender_net, start_rate, rtt)
        # The camera starts on a whole ms, so capture times, deadlines and refreshes are all whole numbers.
        # The player keeps its own copy of the frames, so nothing the sender does to its copy changes the score.
        start = math.ceil(sim.now)
        frames.extend(Frame(i, start + i * FRAME_MS, tuple(v)) for i, v in enumerate(data))
        player.frames = frames
        for frame in frames:
            sim.at(frame.time, endpoints["sender"].on_frame, Frame(frame.id, frame.time, frame.data))
        # The player refreshes at the capture times, after anything else that happens at the same moment,
        # so a frame handed over exactly at its deadline is still shown in time.
        for k in range(1, len(frames) + int(DEADLINE_MS / FRAME_MS) + 1):
            sim.at(start + k * FRAME_MS, player._tick, last=True)

    def joined(passcode):  # Part A is done, so the receiver's side of setup can begin
        if passcode is None:
            return  # the call cannot start
        if "sender" in setups:
            setups["receiver"] = receiver_setup.ReceiverSetup(receiver_net, passcode, receiver_ready)
        else:
            receiver_ready(start_rate, rtt)
            sender_ready()

    for link in (to_receiver, to_sender):
        link.to_lose = {SETUP_NAMES[k]: v for k, v in test.get("setup", {}).get("lose", {}).items()}
    stream = JoinStream(name, random.Random("%s-join" % sc["seed"]), test.get("join", {}))
    try:
        if not has(impl, "join"):
            raise FileNotFoundError
        passcode = load(impl, "join").get_passcode(stream, name)
        join_note = join_summary(passcode, stream, name, test.get("join", {}))
    except NotImplementedError:
        passcode = passcode_for(name)
        join_note = "skipped: join.py is not written yet, so the receiver was given the passcode"
    except FileNotFoundError:
        passcode = passcode_for(name)
        join_note = "skipped: there is no join.py in this folder, so the receiver was given the passcode"
    if passcode is not None and not isinstance(passcode, str):
        raise StudentError("get_passcode should return the passcode as a str, or None, not %s" % type(passcode).__name__)
    if passcode and test.get("setup", {}).get("wrong_passcode"):  # the receiver gets a passcode one letter off
        passcode = passcode[:-1] + ("x" if passcode[-1] != "x" else "y")
    try:
        if sender_setup is None:
            setup_note = "skipped: there is no setup.py in this folder, so the call started at %.0f ms"
        else:
            setups["sender"] = sender_setup.SenderSetup(sender_net, passcode_for(name), start_rate, rtt, sender_ready)
            setup_note = "the call started at %.0f ms"
    except NotImplementedError:
        setup_note = "skipped: setup.py is not written yet, so the call started at %.0f ms"
    wrong = test.get("setup", {}).get("wrong_passcode") and passcode is not None
    sim.at(stream.arrived_at, joined, passcode)

    sim.run(SETUP_TIMEOUT_MS)
    if frames:
        sim.run(frames[-1].time + DEADLINE_MS)
        if wrong:
            setup_note += ", but it should not have: the receiver was given a wrong passcode, as the test file asked"
    else:
        setup_note = "the call never started" if passcode is not None else "no passcode, so the call never started"
        if wrong:
            setup_note += " (as it should: the receiver was given a wrong passcode, as the test file asked)"
        elif passcode is not None and "sender" in setups:
            sent = collections.Counter(p[3] for p in packet_log)
            setup_note += (": your ReceiverSetup sent %d JOINs, your SenderSetup got %d and sent %d ACCEPTs, "
                           "your ReceiverSetup got %d and sent %d CONFIRMs, and your SenderSetup got %d"
                           % (sent[1], delivered["sender", b"\x01"], sent[2], delivered["receiver", b"\x02"],
                              sent[3], delivered["sender", b"\x03"]))
        frames = [Frame(i, SETUP_TIMEOUT_MS + i * FRAME_MS, v) for i, v in enumerate(data)]
    result = score(frames, player)

    outcome = ["not_shown"] * len(frames)
    for _, frame_id, _, kind in player.screen:
        if kind != "glitch":
            outcome[frame_id] = kind
    impl_name = os.path.basename(impl)
    log = dict(scenario=name, impl=impl_name, clip=sc["clip"], freeze_gap_ms=FREEZE_GAP_MS, **result,
               screen=player.screen)
    os.makedirs(os.path.join(HERE, "logs"), exist_ok=True)
    log_path = os.path.join(HERE, "logs", "%s-%s.json" % (name, impl_name))
    with open(log_path, "w") as f:
        json.dump(log, f)
    packets_path = os.path.join(HERE, "logs", "%s-%s-packets.csv" % (name, impl_name))
    with open(packets_path, "w") as f:
        f.write("sent_ms,direction,bytes,first_byte,what_happened,arrives_ms\n")
        for sent, direction, size, first, what, arrives in packet_log:
            f.write("%.3f,%s,%d,%s,%s,%s\n" % (sent, direction, size, "" if first is None else "0x%02x" % first,
                                                what, "" if arrives is None else "%.3f" % arrives))

    record_history("%.3f" % result["score"])
    print("%s with %s" % (name, impl_name))
    print("  join      %s" % join_note)
    print("  setup     %s" % (setup_note % frames[0].time if "%" in setup_note else setup_note))
    print("  score     %.3f   (quality %.3f, minus glitches and freezes)" % (result["score"], result["quality"]))
    print("  frames    %d shown in time, %d shown late, %d not shown"
          % tuple(outcome.count(o) for o in ("in_time", "late", "not_shown")))
    levels = [l for _, _, l, kind in player.screen if kind == "in_time"]
    print("  levels    frames shown in time at each level: %s"
          % ", ".join("%d: %d" % (l, levels.count(l)) for l in range(len(frames[0].data))))
    lags = sorted(t - frames[fid].time for t, fid, _, kind in player.screen if kind in ("in_time", "late"))
    if lags:
        print("  lag       time from capture to screen: typical %.0f ms, worst %.0f ms" % (lags[len(lags) // 2], lags[-1]))
    print("  glitches  %d%s" % (result["glitches"], "" if not result["glitches"] else " (%s)" % ", ".join(
        "%d %s" % (n, kind) for kind, n in player.glitch_kinds.items())))
    print("  freezes   %d, %.0f ms in total" % (result["freezes"], result["freeze_ms"]))
    for direction in ("to receiver", "to sender"):
        what = [p[4] for p in packet_log if p[1] == direction]
        print("  packets   %-12s %d sent, %d lost, %d dropped waiting in line"
              % (direction + ":", len(what), what.count("lost"), what.count("dropped waiting")))
    print("  logs      %s, %s" % (os.path.relpath(log_path), os.path.relpath(packets_path)))
    for side in ("receiver", "sender"):
        if late[side] > 20:
            print("  warning   %d packets starting with 0x01, 0x02 or 0x03 reached the %s after the call had started. Only "
                  "setup messages may start with these bytes: other packets that do go to your setup code or are dropped."
                  % (late[side], side))


if __name__ == "__main__":
    main()
